import{_ as n,a0 as s,w as l,s as a,ao as p,I as m,x as i,a1 as e,A as o}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const C=JSON.parse('{"title":"Vim 起步的五個技巧 | LCTT x X-CMD","titleTemplate":false,"description":"Vim 起步的五個技巧 | LCTT (201608) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Vim 起步的五個技巧 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Vim 起步的五個技巧 | LCTT (201608) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201608/20160721 5 tricks for getting started with Vim","title":"Vim 起步的五個技巧","tag":"201608","desc":""},"relativePath":"201608/20160721 5 tricks for getting started with Vim.md","filePath":"[post].md"}'),u={name:"201608/20160721 5 tricks for getting started with Vim.md"};function d(V,t,f,g,T,v){const r=s("Link");return l(),a("div",null,[t[23]||(t[23]=p('<h1 id="vim-起步的五個技巧" tabindex="-1">Vim 起步的五個技巧 <a class="header-anchor" href="#vim-起步的五個技巧" aria-label="Permalink to “Vim 起步的五個技巧”">​</a></h1><p><img src="https://opensource.com/sites/default/files/styles/image-full-size/public/images/education/BUSINESS_peloton.png?itok=nuMbW9d3" alt=""></p><p>多年來，我一直想學 Vim。如今 Vim 是我最喜歡的 Linux 文本編輯器，也是開發者和系統管理者最喜愛的開源工具。我説的學習，指的是真正意義上的學習。想要精通確實很難，所以我只想要達到熟練的水平。我使用了這麼多年的 Linux ，我會的也僅僅只是打開一個文件，使用上下左右箭頭按鍵來移動光標，切換到插入模式，更改一些文本，保存，然後退出。</p><p>但那只是 Vim 的最最基本的操作。我的技能水平只能讓我在終端使用 Vim 修改文本，但是它並沒有任何一個我想像中強大的文本處理功能。這樣我完全無法用 Vim 發揮出勝出 Pico 和 Nano 的能力。</p><p>所以到底為什麼要學習 Vim？因為我花費了相當多的時間用於編輯文本，而且我知道還有很大的效率提升空間。為什麼不選擇 Emacs，或者是更為現代化的編輯器例如 Atom？因為 Vim 適合我，至少我有一丁點的使用經驗。而且，很重要的一點就是，在我需要處理的系統上很少碰見沒有裝 Vim 或者它的弱化版（Vi）。如果你有強烈的慾望想學習對你來説更給力的 Emacs，我希望這些對於 Emacs 同類編輯器的建議能對你有所幫助。</p><p>花了幾周的時間專注提高我的 Vim 使用技巧之後，我想分享的第一個建議就是必須使用它。雖然這看起來就是明知故問的回答，但事實上它比我所預想的計劃要困難一些。我的大多數工作是在網頁瀏覽器上進行的，而且每次我需要在瀏覽器之外打開並編輯一段文本時，就需要避免下意識地打開 Gedit。Gedit 已經放在了我的快速啓動欄中，所以第一步就是移除這個快捷方式，然後替換成 Vim 的。</p><p>為了更好的學習 Vim，我嘗試了很多。如果你也正想學習，以下列舉了一些作為推薦。</p><h3 id="vimtutor" tabindex="-1">Vimtutor <a class="header-anchor" href="#vimtutor" aria-label="Permalink to “Vimtutor”">​</a></h3><p>通常如何開始學習最好就是使用應用本身。我找到一個小的應用叫 Vimtutor，當你在學習編輯一個文本時它能輔導你一些基礎知識，它向我展示了很多我這些年都忽視的基礎命令。Vimtutor 一般在有 Vim 的地方都能找到它，如果你的系統上沒有 Vimtutor，Vimtutor 可以很容易從你的包管理器上安裝。</p><h3 id="gvim" tabindex="-1">GVim <a class="header-anchor" href="#gvim" aria-label="Permalink to “GVim”">​</a></h3><p>我知道並不是每個人都認同這個，但就是它讓我從使用終端中的 Vim 轉戰到使用 GVim 來滿足我基本編輯需求。反對者表示 GVim 鼓勵使用鼠標，而 Vim 主要是為鍵盤黨設計的。但是我能通過 GVim 的下拉菜單快速找到想找的指令，並且 GVim 可以提醒我正確的指令然後通過敲鍵盤執行它。努力學習一個新的編輯器然後陷入無法解決的困境，這種感覺並不好受。每隔幾分鐘讀一下 man 出來的文字或者使用搜索引擎來提醒你該用的按鍵序列也並不是最好的學習新事物的方法。</p><h3 id="鍵盤表" tabindex="-1">鍵盤表 <a class="header-anchor" href="#鍵盤表" aria-label="Permalink to “鍵盤表”">​</a></h3><p>當我轉戰 GVim，我發現有一個鍵盤的“速查表”來提醒我最基礎的按鍵很是便利。網上有很多這種可用的表，你可以下載、打印，然後貼在你身邊的某一處地方。但是為了我的筆記本鍵盤，我選擇買一沓便籤紙。這些便籤紙在美國不到 10 美元，當我使用鍵盤編輯文本，嘗試新的命令的時候，可以隨時提醒我。</p><h3 id="vimium" tabindex="-1">Vimium <a class="header-anchor" href="#vimium" aria-label="Permalink to “Vimium”">​</a></h3>',14)),m("p",null,[t[2]||(t[2]=i("上文提到，我工作都在瀏覽器上進行。其中一條我覺得很有幫助的建議就是，使用 ",-1)),e(r,{href:"https://github.com/philc/vimium"},{default:o(()=>[...t[0]||(t[0]=[i("Vimium",-1)])]),_:1}),t[3]||(t[3]=i(" 來用增強使用 Vim 的體驗。Vimium 是 Chrome 瀏覽器上的一個開源插件，能用 Vim 的指令快捷操作 Chrome。我發現我只用了幾次使用快捷鍵切換上下文，就好像比之前更熟悉這些快捷鍵了。同樣的擴展 Firefox 上也有，例如 ",-1)),e(r,{href:"http://www.vimperator.org/"},{default:o(()=>[...t[1]||(t[1]=[i("Vimerator",-1)])]),_:1}),t[4]||(t[4]=i("。",-1))]),t[24]||(t[24]=m("h3",{id:"其它人",tabindex:"-1"},[i("其它人 "),m("a",{class:"header-anchor",href:"#其它人","aria-label":"Permalink to “其它人”"},"​")],-1)),t[25]||(t[25]=m("p",null,"毫無疑問，最好的學習方法就是求助於在你之前探索過的人，讓他給你建議、反饋和解決方法。",-1)),t[26]||(t[26]=m("p",null,"如果你住在一個大城市，那麼附近可能會有一個 Vim meetup 小組，或者還有 Freenode IRC 上的 #vim 頻道。#vim 頻道是 Freenode 上最活躍的頻道之一，那上面可以針對你個人的問題來提供幫助。聽上面的人發發牢騷或者看看別人嘗試解決自己沒有遇到過的問題，僅僅是這樣我都覺得很有趣。",-1)),t[27]||(t[27]=m("hr",null,null,-1)),t[28]||(t[28]=m("p",null,"那麼，現在怎麼樣了？到現在為止還不錯。為它所花的時間是否值得就在於之後它為你節省了多少時間。但是當我發現一個新的按鍵序列可以來跳過詞，或者一些相似的小技巧，我經常會收穫意外的驚喜與快樂。每天我至少可以看見，一點點的回報，正在逐漸配得上當初的付出。",-1)),m("p",null,[t[7]||(t[7]=i("學習 Vim 並不僅僅只有這些建議，還有很多。我很喜歡指引別人去 ",-1)),e(r,{href:"http://vim-adventures.com/"},{default:o(()=>[...t[5]||(t[5]=[i("Vim Advantures",-1)])]),_:1}),t[8]||(t[8]=i("，它是一種使用 Vim 按鍵方式進行移動的在線遊戲。而在另外一天我在 ",-1)),e(r,{href:"http://vimgifs.com/"},{default:o(()=>[...t[6]||(t[6]=[i("Vimgifts.com",-1)])]),_:1}),t[9]||(t[9]=i(" 發現了一個非常神奇的虛擬學習工具，那可能就是你真正想要的：用一個小小的 gif 動圖來描述 Vim 操作。",-1))]),t[29]||(t[29]=m("p",null,"你有花時間學習 Vim 嗎？或者是任何需要大量鍵盤操作的程序？那些經過你努力後掌握的工具，你認為這些努力值得嗎？效率的提高有沒有達到你的預期？分享你們的故事在下面的評論區吧。",-1)),t[30]||(t[30]=m("hr",null,null,-1)),m("p",null,[t[11]||(t[11]=i("via: ",-1)),e(r,{href:"https://opensource.com/life/16/7/tips-getting-started-vim"},{default:o(()=>[...t[10]||(t[10]=[i("https://opensource.com/life/16/7/tips-getting-started-vim",-1)])]),_:1})]),m("p",null,[t[15]||(t[15]=i("作者：",-1)),e(r,{href:"https://opensource.com/users/jason-baker"},{default:o(()=>[...t[12]||(t[12]=[i("Jason Baker",-1)])]),_:1}),t[16]||(t[16]=i(" 譯者：",-1)),e(r,{href:"https://github.com/maywanting"},{default:o(()=>[...t[13]||(t[13]=[i("maywanting",-1)])]),_:1}),t[17]||(t[17]=i(" 校對：",-1)),e(r,{href:"https://github.com/wxy"},{default:o(()=>[...t[14]||(t[14]=[i("wxy",-1)])]),_:1})]),m("p",null,[t[20]||(t[20]=i("本文由 ",-1)),e(r,{href:"https://github.com/LCTT/TranslateProject"},{default:o(()=>[...t[18]||(t[18]=[i("LCTT",-1)])]),_:1}),t[21]||(t[21]=i(" 原創編譯，",-1)),e(r,{href:"https://linux.cn/"},{default:o(()=>[...t[19]||(t[19]=[i("Linux中國",-1)])]),_:1}),t[22]||(t[22]=i(" 榮譽推出",-1))])])}const k=n(u,[["render",d]]);export{C as __pageData,k as default};
